// Reformat only notes generated by the October packet inventory import.
// Ordinary garden notes and already formatted notes are left untouched.
export function tidyPacketNotes(notes: string): string {
  const header = notes.match(/^Inventory cataloged October 20, 2026\. Owned: (\d+) (seed packets|bulbs\/corms)\.\s*/);
  if (!header) return notes;
  const count = Number(header[1]);
  const unit = header[2] === "seed packets" ? count === 1 ? "seed packet" : "seed packets" : "bulbs/corms";
  let details = notes.slice(header[0].length);
  for (const sentence of [
    "Purchased as bargain garden supplies.",
    "Original quantity remaining has not been checked.",
    "Quantity confirmed by owner; repeat photos counted once.",
    "Quantity confirmed by owner.",
    "Quantity confirmed by owner: one container tomato packet.",
    "Owner confirmed 2 large-tomato packets total.",
    "Kept as one inventory entry containing the two packets, without assigning unverified separate varieties.",
    "These are label claims, not a locally verified schedule.",
    "One packet; original price printed on packet is not the bargain purchase price.",
  ]) details = details.replaceAll(sentence, "");
  const labels: [RegExp, string][] = [
    [/^\d+(?:\.\d+)? (?:mg|g)\b/i, "Packet weight"],
    [/^(?:sow |start indoors |direct sow |spring and late-summer sowing)/i, "When to sow"],
    [/^(?:depth |sowing depth |planting depth |cover )/i, "Planting depth"],
    [/^germination /i, "Germination"],
    [/^(?:thin |thin\/transplant |transplant |spacing |plant spacing |rows |\d+(?:-inch| bulbs per square foot))/i, "Spacing"],
    [/^(?:label )?height /i, "Height"],
    [/^(?:label )?maturity /i, "Maturity"],
    [/^harvest /i, "Harvest"],
    [/^(?:blooms? |bloom time |summer bloom|early summer bloom)/i, "Flowering"],
    [/^(?:full sun|sun or partial shade|sunny location|label specifies .*sunlight)/i, "Light"],
    [/^(?:labeled )?hardiness zones /i, "Hardiness"],
  ];
  const lines = details.replaceAll("Packet: ", "").split(/;\s*|\.(?=\s+[A-Za-z]|\s*$)|\n+/)
    .map(line => line.trim()).filter(Boolean).map(line => {
      const match = labels.find(([pattern]) => pattern.test(line));
      if (!match) return `- ${line[0].toUpperCase()}${line.slice(1)}`;
      let value = line;
      if (["Germination", "Height", "Maturity", "Harvest", "Hardiness"].includes(match[1])) {
        value = line.replace(/^(?:label |labeled )?(?:germination|height|maturity|harvest|hardiness zones)\s*/i, "");
      } else if (match[1] === "Planting depth" && /^(?:depth |sowing depth |planting depth )/i.test(line)) {
        value = line.replace(/^(?:depth|sowing depth|planting depth)\s*/i, "");
      }
      return `- ${match[1]}: ${value}`;
    });
  return [`Quantity: ${count} ${unit}`, "", ...lines].join("\n");
}
